def investigate(context, acquire):
    values = context["values"]
    if len(values) == 0:
        return 0
    contributions = []
    for i in range(len(values)):
        x = values[i]
        term = -x + 2 * x * x
        if i > 0:
            term = term + 2 * x * values[i - 1]
        contributions.append(term)
    for _ in range(4):
        total = 0
        for i in range(len(contributions)):
            total = total + contributions[i]
            contributions[i] = total
    return contributions[-1]

